    "product has valid UUID",
    /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(
      product.id,
    ),
  );
  TestValidator.predicate("product name is not empty", product.name.length > 0);
