  // 3. Query first page with limit 3
  const page1 =
    await api.functional.shoppingMall.administrator.notificationTemplates.index(
      adminConnection,
      {
        body: { limit: 3 } satisfies IShoppingMallNotificationTemplate.IRequest,
      },
    );
