    channel: "push",
    status: "failed",
    delivered_at: null,
  };
  const updated2 =
    await api.functional.shoppingMall.administrator.notificationDeliveries.update(
      adminConnection,
      {
        notificationDeliveryId: delivery.id,
        body: partialUpdate2,
      },
    );
