    _sum: { base_price: true },
    skip,
    take: limit,
    orderBy: { created_at: "desc" },
  });
  const totalRecords = await MyGlobal.prisma.shopping_mall_sales.count({
    where: whereFilters,
  });
  return {
    data: groupedAggregates.map(
      (item: {
        id: string;
        _sum?: {
