}): Promise<IPageIShoppingMallSaleQuestion.ISummary> {
  const page = 1;
  const limit = 100;
  const skip = 0;
  const where: Prisma.shopping_mall_sale_questionsWhereInput = {
    deleted_at: null,
    shopping_mall_customer_id: props.customer.id,
